// Step 1: fetch() asks the URL for data. fetch() returns a Promise.
// Step 2: .then() runs when the response arrives
// Step 3: response.json() converts the response into usable data
// Step 4: The second .then() runs with the converted data

fetch('https://jsonplaceholder.typicode.com/users/1')
  .then(function(response) {
    return response.json()    // Convert raw response to data object
  })
  .then(function(userData) {
    console.log(userData.name)  // Prints: "Leanne Graham"
  })

// Base URL (the server's address)
let baseUrl = 'https://jsonplaceholder.typicode.com/users/'

// Id of the user we want
let userId = 1

// Combined URL:
let fullUrl = baseUrl + userId
console.log(fullUrl)   // Prints: "https://jsonplaceholder.typicode.com/users/1"

// If userId were 5:
userId = 5
fullUrl = baseUrl + userId
console.log(fullUrl)   // Prints: "https://jsonplaceholder.typicode.com/users/5"

