lesson.content:
// --- .then() version (Lesson 1) ---
function getUser(id) {
  return fetch('https://jsonplaceholder.typicode.com/users/' + id)
    .then(function(res) {
      return res.json()
    })
    .then(function(data) {
      return data.name
    })
}

// --- async/await version (this lesson) ---
async function getUser(id) {
  let url = 'https://jsonplaceholder.typicode.com/users/' + id
  let res = await fetch(url)       // Wait for the response
  let data = await res.json()      // Wait for JSON conversion
  return data.name                 // Return the name (wrapped in Promise automatically)
}

async function getPostTitle(id) {
  // 1. Build the URL (same as before)
  let url = 'https://jsonplaceholder.typicode.com/posts/' + id

  // 2. fetch() returns a Promise. await PAUSES here until the response arrives.
  //    No .then() needed. The response gets saved directly into 'response'.
  let response = await fetch(url)
  //    When this line finishes, 'response' contains the server's full reply.

  // 3. response.json() ALSO returns a Promise. await pauses again.
  //    Once done, 'postData' is the usable JavaScript object.
  let postData = await response.json()
  //    postData looks like: { userId: 1, id: 1, title: "...", body: "..." }

  // 4. Just return the title. Since this is async, JavaScript automatically
  //    wraps the return value in a Promise for the caller.
  return postData.title
  //    The caller gets a Promise that resolves to the title string.
}

// What the API sends back for a post:
{
  "userId": 1,          // The id of the user who wrote this post
  "id": 1,              // The post's own id
  "title": "sunt aut facere repellat...",  // The post title
  "body": "quia et suscipit..."            // The post body/content
}

// To get the title: postData.title
console.log(postData.title)   // Prints: "sunt aut facere repellat provident occaecati excepturi optio reprehenderit"

