lesson.content:
try {
  // Put risky code here
  // If ANY line inside throws an error, execution jumps to catch()
  let result = riskyOperation()
  console.log('Success:', result)  // Only runs if no error
} catch (error) {
  // Handle the error here
  // This runs if anything in the try block failed
  console.log('Oops:', error.message)  // Friendly message instead of crash
}

// This does NOT throw an error even though user 99999 doesn't exist:
async function tryFetch() {
  let res = await fetch('https://jsonplaceholder.typicode.com/users/99999')
  console.log(res.ok)  // Prints: false  (the response is NOT ok, but it's not an error either)
  console.log(res.status)  // Prints: 404  (status code for "not found")
}

// You have to CHECK the response yourself with response.ok
// res.ok is true for status codes 200-299 (success)
// res.ok is false for 404, 500, and other error status codes

async function safeGetUser(id) {
  try {
    // 1. Build the URL. What if id is -1? The URL becomes:
    //    "https://jsonplaceholder.typicode.com/users/-1" — which doesn't exist!
    let url = 'https://jsonplaceholder.typicode.com/users/' + id

    // 2. Fetch the URL
    let response = await fetch(url)

    // 3. Check if the response is OK (status code 200-299)
    //    If it's NOT ok (e.g., 404), we manually throw an error
    if (!response.ok) {
      // This jumps straight to the catch block below
      throw new Error('User not found')
    }

    // 4. Only reached if response WAS ok — convert to JSON
    let userData = await response.json()

    // 5. Return the data on success
    return userData

  } catch (error) {
    // 6. This runs if ANYTHING in the try block threw an error:
    //    - Network failure (no internet)
    //    - Bad URL (typo in domain)
    //    - Our manual throw for !response.ok
    //    - JSON parsing failure
    //
    // 7. Return a clean error object instead of crashing
    //    The error object has two properties:
    return { error: true, message: error.message }
    //    .error is true so the caller knows something went wrong
    //    .message has a human-readable explanation
  }
}

